'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const TYPES={fill:{get name(){return tr('阅读填词')},en:'Complete the Words',section:'Reading',icon:'▤'},daily:{get name(){return tr('生活阅读')},en:'Read in Daily Life',section:'Reading',icon:'▤'},academic:{get name(){return tr('学术阅读')},en:'Read an Academic Passage',section:'Reading',icon:'▤'},email:{get name(){return tr('邮件写作')},en:'Write an Email',section:'Writing',icon:'✎'},discussion:{get name(){return tr('学术讨论')},en:'Academic Discussion',section:'Writing',icon:'✎'},repeat:{get name(){return tr('听与复述')},en:'Listen and Repeat',section:'Speaking',icon:'◉'},interview:{get name(){return tr('模拟面试')},en:'Take an Interview',section:'Speaking',icon:'◉'}};
const BANKMAP=Object.fromEntries(BANK.map(q=>[q.id,q]));const KEY='practice-studio-progress-v1';
let data;try{data=JSON.parse(localStorage.getItem(KEY))}catch{}data={history:[],favorites:[],attempts:{},session:null,mode:'timed',autoGradeWriting:false,...data};
let page='library',section='all',kind='all',search='',pageNum=1,showTime=true,showWords=true,showTranscript=false,recording=false,playing=false,recorder=null,stream=null,recordSeconds=0,recordTimer=null,speechToken=0,currentAudioURL=null,editorHistory=[],editorPosition=-1,storageError=false,mediaBusy=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));if(storageError)toast(tr('保存已恢复'));storageError=false}catch(e){if(!storageError)toast(tr('浏览器存储空间不足，请立即导出备份。'));storageError=true}}
function toast(m){$('#toast').textContent=tr(m);$('#toast').style.display='block';clearTimeout(toast.id);toast.id=setTimeout(()=>$('#toast').style.display='none',3500)}
function iconBrand(){return '<div class="brand"><div class="logo">p.</div><div>Practice Studio<small>YOUR PRACTICE SPACE</small></div></div>'}
function fmt(s){s=Math.max(0,Math.floor(s));return String(Math.floor(s/3600)).padStart(2,'0')+' : '+String(Math.floor(s/60)%60).padStart(2,'0')+' : '+String(s%60).padStart(2,'0')}
function mins(s){return Math.max(1,Math.round(s/60))}
function session(){return data.session}function current(){let s=session();return s?BANKMAP[s.ids[s.index]]:null}function response(q=current()){let s=session();return s.responses[q.id]??(s.responses[q.id]=q.kind==='fill'?Array(q.gaps.length).fill(''):q.questions?{}:'')}
function steps(q){return q.kind==='fill'?1:count(q)}
function count(q){return q.kind==='fill'?q.gaps.length:q.questions?.length||1}
function answered(q,r){if(!r)return 0;return q.kind==='fill'?r.filter(v=>v.trim()).length:q.questions?Object.values(r).filter(Boolean).length:r.trim()?1:0}
function done(id){return Boolean(data.attempts[id]?.completed)}
function go(p,s='all'){page=p;section=s;kind='all';search='';pageNum=1;render()}
function favorites(id){let i=data.favorites.indexOf(id);i<0?data.favorites.push(id):data.favorites.splice(i,1);save();render()}
function render(){if(page==='exam'&&session()){exam();return}dashboard()}
function dashboard(){let totalTime=data.history.reduce((a,h)=>a+h.elapsed,0),complete=Object.values(data.attempts).filter(a=>a.completed).length;
$('#app').innerHTML=L`<div class="layout"><aside class="sidebar">${iconBrand()}<div class="edition">MY WORKSPACE</div><nav>${[['library','all','▦',tr('练习题库')],['library','Reading','▤',tr('阅读练习')],['library','Writing','✎',tr('写作练习')],['library','Speaking','◉',tr('口语练习')],['favorites','all','☆',tr('我的收藏')],['history','all','◷',tr('练习记录')],['importer','all','＋',tr('导入与管理题库')],['settings','all','⚙',tr('设置与备份')]].map(([p,s,i,n])=>`<button class="nav ${page===p&&section===s?'active':''}" data-nav="${p}" data-section="${s}"><span class="icon">${i}</span>${n}</button>`).join('')}</nav><div class="side-bottom"><b>每一次练习，都算数。</b><span class="local-dot"></span>进度保存在当前浏览器<br>自带题库 · 本地练习</div></aside><main class="main"><div class="topline"><span>我的学习空间 <span style="margin:0 10px">/</span> <strong>${page==='importer'?tr('导入与管理题库'):page==='history'?tr('练习记录'):page==='settings'?tr('设置与备份'):page==='favorites'?tr('我的收藏'):tr('练习题库')}</strong></span>${languageSwitcher()}<span class="pill">✦ &nbsp; YOUR OWN MATERIALS</span></div>${page==='importer'?importerPage():page==='settings'?settings():page==='history'?historyPage():L`<div class="hello">A LITTLE PRACTICE, EVERY DAY</div><div class="headline"><div><h1>${page==='favorites'?tr('留给下一次的练习。'):tr('让每次练习，更接近考场。')}</h1><p>导入自己的材料，按自己的节奏练习。</p></div><div class="headline-actions"><button class="btn" data-action="questions">＋ 导入题目</button><button class="btn secondary" data-action="random">随机练一组 ↗</button></div></div>${!BANK.length?emptyBankHTML():''}${page!=='favorites'?L`<div class="hero"><div><small>BRING YOUR OWN QUESTIONS</small><h2>熟悉的界面，真正的练习。</h2><p>青绿色考试界面 · 独立计时 · 作答自动保存<br>从阅读到表达，把知识变成考场上的手感。</p><button class="btn" data-action="combo">开始今日组合 &nbsp; →</button><span style="font-size:10px;color:#acc6bc;margin-left:13px">每个已有题型抽取一组</span></div><div class="hero-art" aria-hidden="true"><div class="book">READING<span>R</span></div><div class="book">WRITING<span>W</span></div><div class="book">SPEAKING<span>S</span></div></div></div><div class="stats"><div class="stat"><div class="label">▦ &nbsp; 已导入题库</div><b>${BANK.length}</b><span>组</span></div><div class="stat"><div class="label">✓ &nbsp; 已完成练习</div><b>${complete}</b><span>/ ${BANK.length}</span></div><div class="stat"><div class="label">◷ &nbsp; 累计练习时长</div><b>${Math.floor(totalTime/60)}</b><span>分钟</span></div><div class="stat"><div class="label">☆ &nbsp; 收藏题目</div><b>${data.favorites.length}</b><span>组</span></div></div>`:''}${session()?L`<div class="recent-resume"><div><b>上次练到这里：${esc(BANKMAP[session().ids[session().index]].title)}</b><p>第 ${session().index+1} / ${session().ids.length} 组 · 已练习 ${fmt(session().elapsed)}</p></div><button class="btn" data-action="resume">继续练习 →</button></div>`:''}<div class="section-title"><div><h2>${page==='favorites'?tr('收藏题目'):tr('练习题库')}</h2><p>材料由你自行导入 · 按组练习，逐题作答</p></div><label class="mode">练习模式 <select id="mode"><option value="timed" ${data.mode==='timed'?'selected':''}>倒计时</option><option value="free" ${data.mode==='free'?'selected':''}>自由练习</option></select></label></div><div class="tabs">${[['all',tr('全部科目'),BANK.length],...['Reading','Writing','Speaking'].map((v,i)=>[v,[tr('阅读'),tr('写作'),tr('口语')][i],BANK.filter(q=>TYPES[q.kind].section===v).length])].map(([s,n,c])=>`<button class="tab ${section===s?'active':''}" data-filter="${s}">${n}<em>${c}</em></button>`).join('')}</div><div class="library-toolbar"><div class="filterrow"><button class="chip ${kind==='all'?'active':''}" data-kind="all">全部题型</button>${Object.entries(TYPES).filter(([k,t])=>section==='all'||t.section===section).map(([k,t])=>`<button class="chip ${kind===k?'active':''}" data-kind="${k}">${t.name}</button>`).join('')}</div><input class="search" id="search" placeholder="搜索主题、关键词或题号…" value="${esc(search)}" aria-label="搜索题库"></div><div class="cards" id="cards"></div><div id="pagination"></div>`}<p class="footer-note">个人题库模拟练习 · 无听力材料，未包含听力科目与写作组句 · 非官方考试或评分服务</p></main></div>`;
$$('[data-nav]').forEach(e=>e.onclick=()=>go(e.dataset.nav,e.dataset.section));$$('[data-filter]').forEach(e=>e.onclick=()=>{section=e.dataset.filter;kind='all';pageNum=1;render()});$$('[data-kind]').forEach(e=>e.onclick=()=>{kind=e.dataset.kind;pageNum=1;render()});if($('#search'))$('#search').oninput=e=>{search=e.target.value;pageNum=1;cards()};if($('#mode'))$('#mode').onchange=e=>{data.mode=e.target.value;save()};bindActions();if($('#cards'))cards();if(page==='history')bindHistory();if(page==='importer')bindImporter();if(window.refreshAIWidgets)window.refreshAIWidgets();}
function $$(s){return [...document.querySelectorAll(s)]}
function filtered(){return BANK.filter(q=>(page!=='favorites'||data.favorites.includes(q.id))&&(section==='all'||TYPES[q.kind].section===section)&&(kind==='all'||q.kind===kind)&&(!search||`${q.title} ${q.number} ${TYPES[q.kind].name} ${q.passage||''} ${q.prompt||''}`.toLowerCase().includes(search.toLowerCase())))}
function cards(){let list=filtered(),slice=list.slice((pageNum-1)*12,pageNum*12);$('#cards').innerHTML=slice.length?slice.map(q=>`<article class="card"><div class="card-top"><span><span class="tag">${TYPES[q.kind].name}</span> &nbsp; #${String(q.number).padStart(2,'0')}</span><button class="star ${data.favorites.includes(q.id)?'on':''}" data-fav="${q.id}" aria-label="${data.favorites.includes(q.id)?tr('取消收藏'):tr('收藏')}">${data.favorites.includes(q.id)?'★':'☆'}</button></div><h3>${esc(q.title)}</h3><p>${TYPES[q.kind].en}</p><div class="card-footer"><span>${count(q)} ${['repeat','interview'].includes(q.kind)?tr('道口语'):q.kind==='fill'?tr('个空格'):tr('道题')} &nbsp; · &nbsp; ${['repeat','interview'].includes(q.kind)?q.seconds+tr(' 秒 / 题'):mins(q.seconds)+tr(' 分钟')} ${done(q.id)?tr(' · ✓ 已完成'):''}</span><button data-start="${q.id}">${done(q.id)?tr('再次练习'):tr('开始练习')} &nbsp; →</button></div></article>`).join(''):tr('<div class="empty">这里还没有题目，试试其他筛选条件。</div>');let max=Math.ceil(list.length/12);$('#pagination').innerHTML=L`<div class="pagination"><button class="chip" id="prevpage" ${pageNum<=1?'disabled':''}>← 上一页</button><span>${list.length?`${pageNum} / ${max}`:'0'} · 共 ${list.length} 组</span><button class="chip" id="nextpage" ${pageNum>=max?'disabled':''}>下一页 →</button></div>`;$('#prevpage').onclick=()=>{pageNum--;cards()};$('#nextpage').onclick=()=>{pageNum++;cards()};$$('[data-fav]').forEach(e=>e.onclick=()=>favorites(e.dataset.fav));$$('[data-start]').forEach(e=>e.onclick=()=>start([e.dataset.start]));}
function bindActions(){bindLanguageControls();$$('[data-action]').forEach(e=>e.onclick=()=>{let a=e.dataset.action;if(a==='random'){let l=filtered();if(l.length)start([l[Math.floor(Math.random()*l.length)].id]);else toast(tr('没有符合筛选条件的题目'))}if(a==='combo'){let ids=Object.keys(TYPES).filter(k=>BANK.some(q=>q.kind===k)).map(k=>{let l=BANK.filter(q=>q.kind===k&&!done(q.id));if(!l.length)l=BANK.filter(q=>q.kind===k);return l[Math.floor(Math.random()*l.length)].id});if(ids.length)start(ids);else go('importer')}if(a==='resume'){page='exam';session().paused=false;session().tick=Date.now();save();render()}if(a==='questions')go('importer');if(a==='demo')loadDemo();if(a==='backup')exportBackup();if(a==='import')$('#importfile').click()});if($('#importfile'))$('#importfile').onchange=importBackup;}
function settings(){return L`<div class="hello">MAKE IT YOURS</div><div class="headline"><div><h1>安心练习，记得备份。</h1><p>题库、作答与录音保存在当前设备的当前浏览器。</p></div></div><div class="settings-card"><h3>备份与恢复</h3><p>完整备份包含你导入的题目、作文、练习进度、收藏与录音。清除浏览器数据或更换网址前请先备份。备份可能包含私人材料，请自行保管。</p><button class="btn" data-action="backup">导出完整备份</button> <button class="btn secondary" data-action="import">恢复完整备份</button><input type="file" id="importfile" accept="application/json,.json" hidden></div><div class="settings-card"><h3>自带题库</h3><p>平台不内置第三方题库。支持阅读填词、生活阅读、学术阅读、邮件写作、学术讨论、听与复述和模拟面试。可以填写表单、导入 JSON，或上传 PDF 自动识别后校对草稿。</p><button class="btn secondary" data-action="questions">导入与管理题库 →</button></div><div class="settings-card"><h3>练习与隐私</h3><p>计时由题目设置，可在练习中调整。口语使用浏览器合成语音；录音留在当前浏览器，暂不提供 AI 录音评分。阅读依据你填写的参考答案核对，缺失答案不计分。</p><p>写作 AI 默认关闭自动提交。点击批改会将所选题目的内容和作文通过本机 Codex 发给模型，使用该电脑自己的登录和额度。本机批改报告保存在 .local-data/ 中；不使用额外 API 密钥。</p></div>`}
function historyPage(){return L`<div class="hello">YOUR PRACTICE JOURNAL</div><div class="headline"><div><h1>每一点进步，都有迹可循。</h1><p>回看作答、核对阅读答案、重听自己的表达。</p></div><button class="btn secondary" data-action="backup">导出备份</button></div>${data.history.length?data.history.slice().reverse().map(h=>L`<article class="history-item"><div><h3>${esc(attemptTitle(h))}</h3><p>${new Date(h.date).toLocaleString(I18N.locale())} &nbsp; · &nbsp; ${fmt(h.elapsed)} &nbsp; · &nbsp; ${h.ids.length} 组题</p></div><button class="btn secondary" data-history="${esc(h.id)}">查看作答 →</button></article>`).join(''):tr('<div class="empty">完成第一组练习后，记录会出现在这里。</div>')}`}
function bindHistory(){$$('[data-history]').forEach(e=>e.onclick=()=>review(data.history.find(h=>h.id===e.dataset.history)))}
function modal(html){$('#dialog').innerHTML=`<div class="overlay"><div class="modal" role="dialog" aria-modal="true" tabindex="-1">${html}</div></div>`;$('.modal').focus()}
function closeModal(){$('#dialog').innerHTML=''}
function start(ids){if(session()){modal(L`<h2>开始新的练习？</h2><p>当前还有一份未交卷练习。你可以继续，也可以先保存为练习记录，再开始新题。</p><div class="modal-actions"><button class="btn secondary" id="keep">继续上次练习</button><button class="btn" id="replace">保存并开始</button></div>`);$('#keep').onclick=()=>{closeModal();page='exam';session().paused=false;session().tick=Date.now();render()};$('#replace').onclick=()=>{finish(false);closeModal();createSession(ids)};return}createSession(ids)}
function createSession(ids){stopMedia();data.session={id:crypto.randomUUID(),ids,index:0,question:0,responses:{},elapsed:0,taskElapsed:{},limits:{},mode:data.mode,paused:false,tick:Date.now(),date:new Date().toISOString()};page='exam';save();showTranscript=false;render()}
function taskLimit(q=current()){return session().limits[q.id]??(q.questions&&['repeat','interview'].includes(q.kind)?q.seconds*q.questions.length:q.seconds)}
function timeString(){let s=session(),q=current(),elapsed=s.taskElapsed[q.id]||0;return fmt(s.mode==='timed'?taskLimit(q)-elapsed:elapsed)}
function exam(){let s=session(),q=current(),t=TYPES[q.kind],n=steps(q),qi=s.question,r=response();$('#app').innerHTML=L`<div class="exam"><header class="exam-header"><div style="display:flex;align-items:center;gap:0"><div class="exam-brand">${iconBrand()}</div><div class="exam-title">【${t.name}】 #${q.number}</div></div><div class="exam-actions">${languageSwitcher()}<button id="exit" aria-label="返回题库">题库</button><button id="pause">暂停考试 Ⅱ</button><button id="back" ${s.index===0&&s.question===0?'disabled':''}>‹ 上一题</button><button class="primary" id="next">${s.index===s.ids.length-1&&s.question===n-1?tr('完成 ✓'):tr('下一题 ›')}</button></div></header><div class="subbar"><div><b>${sectionLabel(t.section)}</b><span class="sep"></span><span>${q.kind==='fill'?'Complete the Words':L`第 ${qi+1} / ${n} 题`}</span></div><div class="timebar"><span class="timer" id="timer" ${showTime?'':'hidden'}>${timeString()}</span><button id="hidetime">${showTime?tr('◉ 隐藏时间'):tr('◉ 显示时间')}</button><button id="adjusttime" aria-label="调整计时">⚙</button></div></div><main class="exam-content" id="exam-content">${q.kind==='fill'?fillView(q,r):['daily','academic'].includes(q.kind)?readingView(q,r):['email','discussion'].includes(q.kind)?writingView(q,r):speakingView(q,r)}</main><footer class="exam-bottom"><div style="display:flex;align-items:center;gap:15px"><span class="source-link">自带题目</span><span>第 ${s.index+1} / ${s.ids.length} 组</span></div><div class="question-dots">${Array.from({length:q.kind==='fill'?1:n},(_,i)=>L`<button class="qdot ${i===qi?'current':''} ${(q.kind==='fill'?answered(q,r):r[i])?'answered':''}" data-question="${i}" aria-label="第 ${i+1} 题">${i+1}</button>`).join('')}</div><span class="saved" id="save-status">✓ 自动保存</span><button class="source-link" id="submit">交卷</button></footer></div>`;
$('#exit').onclick=()=>{if(mediaBusy)return toast(tr('请先结束录音或等待保存完成'));syncTime();stopMedia();s.paused=true;save();page='library';render()};$('#pause').onclick=pause;$('#back').onclick=()=>navigate(-1);$('#next').onclick=()=>navigate(1);$('#submit').onclick=askFinish;$('#hidetime').onclick=()=>{showTime=!showTime;$('#timer').hidden=!showTime;$('#hidetime').textContent=showTime?tr('◉ 隐藏时间'):tr('◉ 显示时间')};$('#adjusttime').onclick=adjustTime;$$('[data-question]').forEach(e=>e.onclick=()=>{if(mediaBusy)return toast(tr('请先结束录音或等待保存完成'));stopMedia();s.question=+e.dataset.question;showTranscript=false;save();exam()});
bindLanguageControls();if(q.kind==='fill')bindFill(q);else if(['daily','academic'].includes(q.kind))bindReading(q);else if(['email','discussion'].includes(q.kind))bindEditor(q);else bindSpeaking(q);}
function fillView(q,r){let html='',last=0;q.gaps.forEach((g,i)=>{let len=g.answer?.toLowerCase().startsWith(g.prefix.toLowerCase())?g.answer.length-g.prefix.length:g.length;html+=esc(q.passage.slice(last,g.start))+L`<span class="gapword">${esc(g.prefix)}<input class="gap" data-gap="${i}" style="width:${Math.max(25,len*17+9)}px" autocomplete="off" autocapitalize="none" spellcheck="false" aria-label="空格 ${i+1}，补全 ${esc(g.prefix)}" maxlength="${len}" value="${esc(r[i]||'')}"></span>`;last=g.end});html+=esc(q.passage.slice(last));return L`<h1 class="exam-heading">补全段落中单词缺失的字母。</h1><div class="fill-wrap"><div class="fill-passage">${html}</div></div>`}
function bindFill(q){$$('[data-gap]').forEach((e,i,all)=>{e.oninput=()=>{let r=response();r[i]=e.value.replace(/[^a-z]/gi,'');e.value=r[i];save();if(e.value.length===e.maxLength&&i<all.length-1)all[i+1].focus()};e.onkeydown=ev=>{if(ev.key==='Backspace'&&!e.value&&i){all[i-1].focus();ev.preventDefault()}if(ev.key==='Enter'){ev.preventDefault();if(i<all.length-1)all[i+1].focus();else askFinish()}}})}
function paragraphs(t){return esc(t).split(/\n+/).map(p=>`<p>${p}</p>`).join('')}
function normalizeMarkers(t){let i=0;return t.replace(/\[?\s*[\uf0a2\uf0a0■]\s*\]?/g,()=>` [${++i}] `)}
function readingView(q,r){let x=q.questions[session().question];return `<h1 class="exam-heading">${q.kind==='daily'?esc(q.title.replace(/^Read/i,'Read')):tr('阅读一篇学术文章。')}</h1><div class="reading-grid"><article class="passage-panel">${q.kind==='academic'?`<h2>${esc(q.title)}</h2>`:''}<div class="${q.kind==='daily'?'daily-letter':''}">${paragraphs(normalizeMarkers(q.passage))}</div></article><section class="question-panel"><h3>${esc(normalizeMarkers(x.stem))}</h3>${x.options.length?`<div class="choices">${x.options.map(o=>`<label class="choice ${r[session().question]===o.label?'selected':''}"><input type="radio" name="answer" value="${esc(o.label)}" ${r[session().question]===o.label?'checked':''}><span><span class="option-label">${esc(o.label)}</span>${esc(normalizeMarkers(o.text))}</span></label>`).join('')}</div>`:L`<p style="font:13px var(--font);color:var(--muted)">复制或输入你选择的完整原文句子：</p><textarea id="sentenceanswer" class="search" spellcheck="false" aria-label="选择的原文句子">${esc(r[session().question]||'')}</textarea>`}</section></div>`}
function bindReading(q){$$('input[name=answer]').forEach(e=>e.onchange=()=>{response()[session().question]=e.value;save();$$('.choice').forEach(l=>l.classList.toggle('selected',l.querySelector('input').checked));markAnswered()});if($('#sentenceanswer'))$('#sentenceanswer').oninput=e=>{response()[session().question]=e.target.value;save();markAnswered()}}
function markAnswered(){let el=$(`.qdot[data-question="${session().question}"]`);if(el)el.classList.add('answered')}
function promptHTML(q){return esc(q.prompt)}
function writingView(q,r){return L`<div class="writing-grid"><article class="prompt-panel">${promptHTML(q)}</article><section class="response-panel"><div class="response-label">你的作答：</div>${q.kind==='email'?L`<div class="email-meta">收件人：${esc(q.to)}<br>主题：${esc(q.subject)}</div>`:tr('<div class="email-meta">撰写一段内容，参与讨论。<br><small style="font-size:13px;color:var(--muted)">用自己的话表达并支持你的观点。</small></div>')}<div class="editor"><div class="editor-tools"><button id="cut">剪切</button><button id="paste">粘贴</button><button id="undo">撤销</button><button id="redo">重做</button><button class="word-toggle" id="words">${showWords?tr('◉ 隐藏'):tr('◉ 显示')} 字数 <span id="wordcount">${showWords?wordCount(r):''}</span></button></div><textarea id="essay" aria-label="你的作答" spellcheck="false" autocomplete="off" autocapitalize="off" placeholder="">${esc(r)}</textarea></div></section></div>`}
function wordCount(s){return (s.trim().match(/\S+/g)||[]).length}
function bindEditor(q){let e=$('#essay');editorHistory=[e.value];editorPosition=0;const changed=()=>{session().responses[q.id]=e.value;save();if($('#wordcount'))$('#wordcount').textContent=showWords?wordCount(e.value):''};e.oninput=()=>{editorHistory=editorHistory.slice(0,editorPosition+1);editorHistory.push(e.value);editorPosition++;changed()};$('#words').onclick=()=>{showWords=!showWords;$('#words').innerHTML=L`${showWords?tr('◉ 隐藏'):tr('◉ 显示')} 字数 <span id="wordcount">${showWords?wordCount(e.value):''}</span>`};$('#undo').onclick=()=>{if(editorPosition>0){e.value=editorHistory[--editorPosition];changed()}};$('#redo').onclick=()=>{if(editorPosition<editorHistory.length-1){e.value=editorHistory[++editorPosition];changed()}};$('#cut').onclick=async()=>{let a=e.selectionStart,b=e.selectionEnd;if(a===b){toast(tr('先选中要剪切的文字'));return}try{await navigator.clipboard.writeText(e.value.slice(a,b));e.setRangeText('',a,b,'end');e.dispatchEvent(new Event('input'));e.focus()}catch{toast(tr('请用键盘快捷键剪切：⌘X / Ctrl+X'))}};$('#paste').onclick=async()=>{try{let s=await navigator.clipboard.readText();e.setRangeText(s,e.selectionStart,e.selectionEnd,'end');e.dispatchEvent(new Event('input'));e.focus()}catch{toast(tr('请用键盘快捷键粘贴：⌘V / Ctrl+V'))}};}
function speakingView(q,r){let qi=session().question;return L`<div class="speaking-wrap"><p class="speaking-eyebrow">${esc(q.title)} · ${qi+1} / ${q.questions.length}</p><h1 class="exam-heading">${q.kind==='repeat'?tr('听一遍，然后复述。'):tr('听问题，然后作答。')}</h1><div class="audio-stage"><div class="sound-bars" id="soundbars">${'<i></i>'.repeat(18)}</div><button class="btn" id="listen" ${session().mode==='timed'&&session().played?.[q.id+'-'+qi]?'disabled':''}>${session().mode==='timed'&&session().played?.[q.id+'-'+qi]?tr('✓ 已播放'):tr('▶ &nbsp; 播放题目')}</button></div><div class="speak-controls"><button class="btn record-btn" id="record">● &nbsp; 开始录音</button><button class="btn secondary" id="transcript">${showTranscript?tr('隐藏'):tr('查看')}题目文字</button></div><p class="speech-status" id="speechstatus">先听题，再录音作答 · 建议时限 ${q.seconds} 秒 · ${session().mode==='timed'?tr('每题仅播放一次'):tr('自由模式可重复播放')}</p><div id="transcriptbody">${showTranscript?`<div class="transcript">${esc(q.questions[qi].stem)}</div>`:''}</div><div id="recording"></div><p class="speaking-notes">题目通过浏览器英文合成语音播放 · 非原版音频<br>录音存储在当前浏览器，可回放、下载与备份。进入下一题前请先停止录音。</p></div>`}
function db(){return new Promise((resolve,reject)=>{let req=indexedDB.open('practice-studio-audio',1);req.onupgradeneeded=()=>req.result.createObjectStore('audio');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function getAudio(key){let d=await db();return new Promise((resolve,reject)=>{let tx=d.transaction('audio');let r=tx.objectStore('audio').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);tx.oncomplete=()=>d.close()})}
async function putAudio(key,blob){let d=await db();return new Promise((resolve,reject)=>{let tx=d.transaction('audio','readwrite');tx.objectStore('audio').put(blob,key);tx.oncomplete=()=>{d.close();resolve()};tx.onerror=()=>reject(tx.error)})}
async function audioPlayer(key,target){try{let b=await getAudio(key);if(!b)return;if(currentAudioURL)URL.revokeObjectURL(currentAudioURL);currentAudioURL=URL.createObjectURL(b);if(target?.isConnected)target.innerHTML=L`<div class="recording"><audio src="${currentAudioURL}" controls></audio><br><a href="${currentAudioURL}" download="practice-${esc(key)}.${b.type.includes('mp4')?'m4a':'webm'}">↓ 下载这段录音</a></div>`}catch{toast(tr('无法读取录音，请检查浏览器存储权限'))}}
function bindSpeaking(q){$('#listen').onclick=()=>speak(q.questions[session().question].stem);$('#record').onclick=toggleRecord;$('#transcript').onclick=()=>{showTranscript=!showTranscript;$('#transcript').textContent=(showTranscript?tr('隐藏'):tr('查看'))+tr('题目文字');$('#transcriptbody').innerHTML=showTranscript?`<div class="transcript">${esc(q.questions[session().question].stem)}</div>`:''};let key=response()[session().question];if(key)audioPlayer(key,$('#recording'));}
function speak(text){if(recording||mediaBusy)return toast(tr('请先结束录音或等待保存'));if(!('speechSynthesis'in window))return toast(tr('此浏览器不支持英文朗读，可以查看题目文字练习'));speechSynthesis.cancel();let token=++speechToken;let u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.92;let voices=speechSynthesis.getVoices(),voice=voices.find(v=>v.lang==='en-US'&&v.localService)||voices.find(v=>v.lang.startsWith('en'));if(voice)u.voice=voice;u.onstart=()=>{if(token!==speechToken)return;playing=true;let s=session();s.played??={};s.played[current().id+'-'+s.question]=true;save();$('#soundbars')?.classList.add('playing');if($('#speechstatus'))$('#speechstatus').textContent=tr('正在播放题目，请仔细听…');if($('#listen'))$('#listen').disabled=true};u.onend=()=>{if(token!==speechToken)return;playing=false;$('#soundbars')?.classList.remove('playing');if($('#speechstatus'))$('#speechstatus').textContent=tr('播放结束。准备好后，点击开始录音。');if($('#listen')){$('#listen').disabled=session().mode==='timed';if(session().mode==='timed')$('#listen').textContent=tr('✓ 已播放')}};u.onerror=()=>{if(token!==speechToken)return;playing=false;let s=session();if(s?.played)delete s.played[current().id+'-'+s.question];save();$('#soundbars')?.classList.remove('playing');if($('#listen'))$('#listen').disabled=false;toast(tr('英文朗读不可用，请安装系统英文语音，或查看文字练习'))};speechSynthesis.speak(u)}
async function toggleRecord(){if(recording){stopRecording();return}if(mediaBusy)return;if(playing)return toast(tr('请等待题目播放结束'));if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast(tr('录音需要支持麦克风的浏览器，并通过 HTTPS 或 localhost 打开'));let s=session(),q=current(),qi=s.question;mediaBusy=true;$('#record').disabled=true;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});let chunks=[],sid=s.id,key=`${sid}-${q.id}-${qi}-${Date.now()}`;recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{clearInterval(recordTimer);stream?.getTracks().forEach(t=>t.stop());recording=false;try{let blob=new Blob(chunks,{type:recorder.mimeType});if(!blob.size)throw new Error('empty');await putAudio(key,blob);if(session()?.id===sid){response(q)[qi]=key;save()}if(page==='exam'&&session()?.id===sid&&current().id===q.id&&session().question===qi){await audioPlayer(key,$('#recording'));markAnswered();$('#speechstatus').textContent=L`录音已保存 · ${recordSeconds} 秒`;$('#record').textContent=tr('● 重新录音');$('#record').classList.remove('active');$('#record').disabled=false}toast(tr('录音已保存'))}catch{toast(tr('录音保存失败，请检查浏览器存储空间'));if($('#record')){$('#record').disabled=false;$('#record').textContent=tr('● 重新录音');$('#record').classList.remove('active')}}finally{mediaBusy=false}};recorder.start();recording=true;recordSeconds=0;$('#record').disabled=false;$('#record').textContent=tr('■ 停止录音');$('#record').classList.add('active');$('#speechstatus').textContent=L`录音中 0 / ${q.seconds} 秒`;recordTimer=setInterval(()=>{recordSeconds++;if($('#speechstatus'))$('#speechstatus').textContent=L`录音中 ${recordSeconds} / ${q.seconds} 秒`;if(recordSeconds>=q.seconds)stopRecording()},1000)}catch(e){stream?.getTracks().forEach(t=>t.stop());mediaBusy=false;$('#record').disabled=false;toast(e.name==='NotAllowedError'?tr('麦克风未获授权，请在地址栏设置中允许麦克风。'):tr('无法使用麦克风，请检查设备与浏览器权限。'))}}
function stopRecording(){if(recorder?.state==='recording'){clearInterval(recordTimer);recorder.stop();recording=false;if($('#record')){$('#record').textContent=tr('正在保存…');$('#record').disabled=true}}}
function stopMedia(){speechToken++;if('speechSynthesis'in window)speechSynthesis.cancel();playing=false;if(currentAudioURL){URL.revokeObjectURL(currentAudioURL);currentAudioURL=null}}
function syncTime(){let s=session();if(!s||s.paused)return;let now=Date.now(),delta=Math.max(0,(now-s.tick)/1000);s.elapsed+=delta;let q=current();s.taskElapsed[q.id]=(s.taskElapsed[q.id]||0)+delta;s.tick=now}
function pause(){if(mediaBusy)return toast(tr('请先停止录音并等待保存'));syncTime();stopMedia();session().paused=true;save();modal(tr('<h2>考试已暂停</h2><p>已暂停计时，作答已保存在当前浏览器。准备好后继续。</p><div class="modal-actions"><button class="btn" id="continue">继续考试 →</button></div>'));$('#continue').onclick=()=>{session().paused=false;session().tick=Date.now();save();closeModal()}}
function adjustTime(){if(mediaBusy)return toast(tr('请先结束录音'));syncTime();let s=session();s.paused=true;let q=current();modal(L`<h2>调整本组计时</h2><p>阅读时长是训练设置，可按自己的节奏调整。修改后会重置本组计时。</p><label>分钟 <input class="search" id="newminutes" type="number" min="1" max="120" value="${Math.ceil(taskLimit(q)/60)}"></label><div class="modal-actions"><button class="btn secondary" id="cancel-time">取消</button><button class="btn" id="settime">应用并重新计时</button></div>`);let resume=()=>{s.paused=false;s.tick=Date.now();save();closeModal()};$('#cancel-time').onclick=resume;$('#settime').onclick=()=>{let v=+$('#newminutes').value;if(!Number.isFinite(v)||v<1||v>120)return toast(tr('请输入 1–120 分钟'));s.limits[q.id]=v*60;s.taskElapsed[q.id]=0;resume();exam()}}
function navigate(delta){if(mediaBusy)return toast(tr('请先停止录音并等待保存'));syncTime();stopMedia();let s=session(),q=current();if(delta>0){if(s.question<steps(q)-1)s.question++;else if(s.index<s.ids.length-1){s.index++;s.question=0}else return askFinish()}else{if(s.question>0)s.question--;else if(s.index>0){s.index--;s.question=steps(current())-1}}s.tick=Date.now();showTranscript=false;save();exam()}
function askFinish(){if(mediaBusy)return toast(tr('请先停止录音并等待保存'));syncTime();let s=session();s.paused=true;stopMedia();save();let n=s.ids.reduce((a,id)=>a+count(BANKMAP[id])-answered(BANKMAP[id],s.responses[id]),0);modal(L`<h2>结束这次练习？</h2><p>${n?L`还有 ${n} 项未完成。你可以继续作答，也可以现在交卷。`:tr('本次作答已完成，可以交卷查看记录。')} 作文和录音会保留。</p><div class="modal-actions"><button class="btn secondary" id="cancel-submit">继续作答</button><button class="btn" id="confirm-submit">交卷并查看</button></div>`);$('#cancel-submit').onclick=()=>{s.paused=false;s.tick=Date.now();save();closeModal()};$('#confirm-submit').onclick=()=>finish(true)}
function finish(show=true){syncTime();stopMedia();let s=session();if(!s)return;let h={...s,title:s.ids.length===1?`${TYPES[BANKMAP[s.ids[0]].kind].name} · ${BANKMAP[s.ids[0]].title}`:tr('今日组合练习'),date:new Date().toISOString()};delete h.tick;delete h.paused;data.history.push(h);for(let id of s.ids)data.attempts[id]={completed:answered(BANKMAP[id],s.responses[id])===count(BANKMAP[id]),date:h.date};data.session=null;save();page='history';closeModal();render();if(show){review(h);if(window.autoGradeAttempt)window.autoGradeAttempt(h)}}
function norm(s){return String(s||'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function grades(h){let result=[];for(let id of h.ids){let q=BANKMAP[id],r=h.responses[id];if(q.kind==='fill')q.gaps.forEach((g,i)=>{let input=r?.[i]||'',v=g.prefix+input;result.push({q,index:i,mine:input?v:tr('未作答'),expected:g.answer,correct:g.answer?norm(v)===norm(g.answer):null})});else if(['daily','academic'].includes(q.kind))q.questions.forEach((x,i)=>{let v=r?.[i]||'';result.push({q,index:i,mine:v||tr('未作答'),expected:x.answer,stem:x.stem,correct:x.answer?norm(v)===norm(x.answer):null})})}return result}
function review(h){let gs=grades(h),known=gs.filter(g=>g.expected),good=known.filter(g=>g.correct).length;modal(L`<h2>练习完成，留一点时间复盘。</h2><p>${esc(attemptTitle(h))} · ${fmt(h.elapsed)}</p>${gs.length?L`<div class="review-score"><div>阅读客观题核对<br><small>依据导入题目中的参考答案</small></div><b>${good}<span style="font-size:15px"> / ${known.length}</span></b></div>${gs.some(g=>!g.expected)?tr('<p>部分题目没有参考答案，标为“需自查”，未计入核对分母。</p>'):''}`:''}${h.ids.map(id=>{let q=BANKMAP[id],r=h.responses[id];return `<div class="review-line"><b>${TYPES[q.kind].name} #${q.number} · ${esc(q.title)}</b> &nbsp; ${['email','discussion'].includes(q.kind)?L`<p>${wordCount(r||'')} words · 原始作答</p><pre>${esc(r||tr('未作答'))}</pre><div data-ai-task="${esc(q.id)}"></div>`:['repeat','interview'].includes(q.kind)?q.questions.map((x,i)=>L`<details><summary>第 ${i+1} 题 · ${r?.[i]?tr('已录音'):tr('未录音')}</summary><p>${esc(x.stem)}</p>${r?.[i]?L`<button class="btn secondary play-history" data-audio="${esc(r[i])}">回放录音</button><div class="history-audio"></div>`:''}</details>`).join(''):gs.filter(g=>g.q.id===id).map(g=>L`<details><summary><span class="${g.correct?'ok':'bad'}">${g.expected?(g.correct?'✓':'×'):'?'} 第 ${g.index+1} ${q.kind==='fill'?tr('空'):tr('题')} &nbsp; ${esc(g.mine)}</span><span style="color:var(--muted)"> &nbsp; ${g.expected?tr('参考：')+esc(g.expected):tr('未填写答案，需自查')}</span></summary>${g.stem?`<p>${esc(g.stem)}</p>`:''}</details>`).join('')}</div>`}).join('')}<p>阅读结果用于练习核对，非官方分数。写作可使用本机 AI 批改；口语录音暂不评分。</p><div class="modal-actions"><button class="btn secondary" id="export-attempt">导出本次作答</button><button class="btn" id="close-review">返回记录</button></div>`);$('#close-review').onclick=closeModal;$('#export-attempt').onclick=()=>download(JSON.stringify(h,null,2),'practice-attempt-'+h.date.slice(0,10)+'.json','application/json');$$('.play-history').forEach(e=>e.onclick=()=>audioPlayer(e.dataset.audio,e.nextElementSibling));$('.modal').dataset.attemptId=h.id;if(window.mountAIReview)window.mountAIReview(h);}
function download(content,name,type){let blob=content instanceof Blob?content:new Blob([content],{type});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
async function exportBackup(){try{toast(tr('正在整理完整备份…'));let d=await db(),audio=await new Promise((res,rej)=>{let tx=d.transaction('audio'),s=tx.objectStore('audio'),a=[];let r=s.openCursor();r.onsuccess=()=>{let c=r.result;if(c){a.push([c.key,c.value]);c.continue()}else res(a)};r.onerror=()=>rej(r.error);tx.oncomplete=()=>d.close()});let audios=[];for(let [key,blob]of audio){let b64=await new Promise((res,rej)=>{let f=new FileReader();f.onload=()=>res(f.result);f.onerror=rej;f.readAsDataURL(blob)});audios.push({key,data:b64})}download(JSON.stringify({version:1,app:'practice-studio',exportedAt:new Date().toISOString(),questions:BANK,data,audios}),'practice-studio-backup-'+new Date().toISOString().slice(0,10)+'.json','application/json');toast(tr('完整备份已导出'))}catch{toast(tr('备份读取失败，请检查浏览器存储权限'))}}
async function importBackup(e){let file=e.target.files[0];if(!file)return;try{if(file.size>40000000)throw Error(tr('备份过大，最多支持 40 MB'));let b=JSON.parse(await file.text());if(b.app!=='practice-studio'||b.version!==1)throw Error(tr('备份格式不匹配'));let questions=PracticeBank.validate(b.questions),map=new Map(questions.map(q=>[q.id,q]));if(!b.data||!Array.isArray(b.data.history)||!Array.isArray(b.data.favorites)||!b.data.attempts||typeof b.data.attempts!=='object'||Array.isArray(b.data.attempts))throw Error(tr('备份数据不完整'));let valid=h=>h&&typeof h.id==='string'&&typeof h.title==='string'&&Array.isArray(h.ids)&&h.ids.length&&h.ids.every(id=>map.has(id))&&h.responses&&typeof h.responses==='object'&&Number.isFinite(h.elapsed)&&h.ids.every(id=>{let q=map.get(id),r=h.responses[id];return r===undefined||(['email','discussion'].includes(q.kind)?typeof r==='string':q.kind==='fill'?Array.isArray(r)&&r.every(v=>typeof v==='string'):r&&typeof r==='object'&&Object.values(r).every(v=>typeof v==='string'))});if(!b.data.history.every(valid)||(b.data.session&&!valid({...b.data.session,title:''}))||!b.data.favorites.every(id=>map.has(id)))throw Error(tr('备份的题库与记录不匹配'));if(!Array.isArray(b.audios)||!b.audios.every(a=>a&&typeof a.key==='string'&&typeof a.data==='string'&&/^data:audio\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]*$/i.test(a.data)))throw Error(tr('录音数据无效'));modal(tr('<h2>恢复这份备份？</h2><p>将替换当前题库、作答、收藏、记录和录音。建议先导出当前备份。</p><div class="modal-actions"><button class="btn secondary" id="cancel-import">取消</button><button class="btn" id="confirm-import">恢复备份</button></div>'));$('#cancel-import').onclick=closeModal;$('#confirm-import').onclick=async()=>{try{$('#confirm-import').disabled=true;let next={...b.data,autoGradeWriting:false,aiJobs:undefined};if(next.session){next.session.paused=true;next.session.tick=Date.now()}for(let h of next.history)delete h.aiJobs;let audioBlobs=[];for(let a of b.audios)audioBlobs.push([a.key,await(await fetch(a.data)).blob()]);commitBankAndProgress(questions,next);let d=await db();await new Promise((resolve,reject)=>{let tx=d.transaction('audio','readwrite');tx.objectStore('audio').clear();for(let [key,blob]of audioBlobs)tx.objectStore('audio').put(blob,key);tx.oncomplete=()=>{d.close();resolve()};tx.onerror=()=>{d.close();reject(tx.error)}});location.reload()}catch(error){toast(tr('恢复未完成：')+error.message);if($('#confirm-import'))$('#confirm-import').disabled=false}}}catch(error){toast(error.message||tr('这不是有效的 Practice Studio 备份'))}}
setInterval(()=>{if(page!=='exam'||!session()||session().paused)return;syncTime();let s=session(),q=current(),el=$('#timer');if(el){el.textContent=timeString();el.classList.toggle('low',s.mode==='timed'&&taskLimit(q)-(s.taskElapsed[q.id]||0)<60)}if(s.mode==='timed'&&(s.taskElapsed[q.id]||0)>=taskLimit(q)){if(recording)stopRecording();if(!mediaBusy){s.paused=true;stopMedia();save();modal(tr('<h2>时间到</h2><p>本组练习时间已到，当前作答已保存。可以交卷，或增加时间继续练习。</p><div class="modal-actions"><button class="btn secondary" id="moretime">增加 5 分钟</button><button class="btn" id="time-finish">查看交卷</button></div>'));$('#moretime').onclick=()=>{s.limits[q.id]=taskLimit(q)+300;s.paused=false;s.tick=Date.now();save();closeModal();exam()};$('#time-finish').onclick=()=>{closeModal();askFinish()}}}save()},1000);
window.addEventListener('pagehide',()=>{syncTime();if(session())session().paused=true;save();stopMedia()});window.addEventListener('pageshow',()=>{if(page==='exam'&&session()?.paused&&!$('.overlay'))pause()});if(session()){session().paused=true;session().tick=Date.now();save()}render();
